import { tx, type JhsPreviewUnit } from './jhs-preview-units';
const unit = (page: number, value: Omit<JhsPreviewUnit, 'id'>): JhsPreviewUnit => ({
  id: `competency-gh-science-b7-nacca2020-p${String(page).padStart(3, '0')}-r01`, ...value,
});

/** Explicit drafts from SCIENCE.pdf PDF pages 53–62; independent review pending. */
export const B7_SCIENCE_SYSTEMS: JhsPreviewUnit[] = [
  unit(53, {
    title: tx('Food, nutrients and why humans eat', 'Aliments, nutriments et besoins humains'),
    subskills: ['explain-food-and-nutrients', 'link-feeding-to-body-needs', 'interpret-comparison-without-body-diagnosis'], misconception: 'diagnoses-nutritional-health-by-appearance',
    explanation: tx('Food supplies substances the body uses for energy, growth, repair and regulation. Carbohydrates and fats can provide energy; proteins supply building materials; vitamins, minerals and water support many body processes. Fibre helps normal bowel function. Many foods contain several nutrients: yam is a source of starch, beans contain protein and carbohydrate, and palm oil supplies fat. Eating enough of a varied, appropriate diet supports life; inadequate intake over time can impair energy, growth and functioning. A person’s appearance alone cannot establish nutritional health or the cause of a change. Discuss the curriculum comparison using respectful teacher-selected fictional cases with stated feeding histories, never body-ranking classmates or deliberately missing meals. Distinguish pictured observations from conclusions that need other evidence.', 'Les aliments apportent des substances utiles à l’énergie, à la croissance, à la réparation et à la régulation. Glucides et lipides peuvent fournir de l’énergie ; les protéines apportent des matériaux ; vitamines, minéraux et eau participent à de nombreuses fonctions. Les fibres aident le transit. Un aliment peut contenir plusieurs nutriments : amidon dans l’igname, protéines et glucides dans les haricots, lipides dans l’huile de palme. Une alimentation suffisante, variée et adaptée soutient la vie ; un apport insuffisant prolongé peut affecter énergie, croissance et fonctionnement. L’apparence seule ne permet pas de diagnostiquer la nutrition ni ses causes. Utilise des situations fictives respectueuses avec histoires alimentaires données, sans classer les corps des camarades ni sauter des repas. Distingue observation et conclusion demandant d’autres preuves.'),
    example: tx('Make a table for a fictional meal of boiled yam, beans, vegetables and water: food → nutrient examples → body use. Explain that the table is not a personalised prescription. In two teacher-provided fictional illustrations with stated adequate versus inadequate intake, describe only what is depicted, connect the histories to possible effects and explain why appearance does not prove an individual diagnosis.', 'Fais un tableau pour un repas fictif d’igname bouillie, haricots, légumes et eau : aliment → exemples de nutriments → rôle. Ce n’est pas une prescription personnelle. Pour deux illustrations fictives fournies, avec apports suffisants ou insuffisants indiqués, décris ce qui est représenté, explique les effets possibles et pourquoi l’apparence ne prouve pas un diagnostic individuel.'),
    question: tx('What can you conclude about a person’s nutritional health from appearance alone?', 'Que peut-on conclure sur la santé nutritionnelle d’une personne à partir de son apparence seule ?'),
    options: { en: ['Appearance alone is insufficient to establish nutritional health or cause', 'Anyone who looks strong must have every needed nutrient', 'Body shape alone proves exactly what a person eats'], fr: ['L’apparence seule ne suffit pas à établir l’état nutritionnel ni sa cause', 'Une personne paraissant forte possède forcément tous les nutriments', 'La silhouette prouve exactement ce qu’une personne mange'] },
    correction: tx('Separate an observation from a diagnosis. Food supplies nutrients, but appearance is not a direct measurement of every nutrient or a complete feeding history. Use the stated fictional evidence, explain possible effects without labelling real people, then retry.', 'Distingue observation et diagnostic. Les aliments fournissent des nutriments, mais l’apparence ne mesure pas chacun d’eux et ne révèle pas toute l’histoire alimentaire. Utilise les faits fictifs donnés sans étiqueter des personnes réelles, puis réessaie.'),
    tasks: [tx('Independently define food, identify nutrient examples in familiar Ghanaian foods and explain energy, growth, repair and regulation. Compare two respectful teacher-provided fictional illustrations/cases with stated feeding histories, distinguishing depicted features from unsupported diagnoses. Deduce why feeding matters and show your actual table and explanation to your teacher.', 'Définis seul les aliments, repère des nutriments d’aliments ghanéens familiers et explique énergie, croissance, réparation et régulation. Compare deux illustrations/situations fictives respectueuses fournies avec histoires alimentaires connues, sans diagnostic non prouvé. Déduis l’importance de se nourrir et présente ton vrai tableau et ton explication.'), tx('Create an independent food–nutrient–function chart using a different set of local food examples. Explain possible effects of insufficient intake using a fictional comparison supplied by your teacher, acknowledge that foods contain multiple nutrients and state the limits of judging health by appearance.', 'Crée seul un autre tableau aliments–nutriments–fonctions. Explique les effets possibles d’un apport insuffisant avec une comparaison fictive fournie, reconnais qu’un aliment contient plusieurs nutriments et précise les limites de l’apparence.')],
    transfer: [tx('Evaluate a fictional school poster claiming body appearance proves a complete diet. Replace it with an accurate food–nutrient–function explanation and a respectful evidence-based comparison. Do not collect personal body measurements or diagnose classmates.', 'Évalue une affiche fictive affirmant que l’apparence prouve une alimentation complète. Remplace-la par des liens exacts aliments–nutriments–fonctions et une comparaison respectueuse documentée. Aucune mesure corporelle personnelle ni diagnostic des camarades.'), tx('For a new teacher-provided fictional meal and feeding history, explain which body needs the foods can support and what cannot be concluded from the information. Defend your reasoning to your teacher without prescribing a personal diet.', 'Pour un nouveau repas et une histoire fictifs fournis, explique les besoins soutenus et les conclusions impossibles. Justifie ton raisonnement à l’enseignant sans prescrire de régime personnel.')],
    retention: [tx('Why do humans need food as well as an energy source?', 'Pourquoi les humains ont-ils besoin d’aliments au-delà de leur apport énergétique ?'), tx('Can one food contain several types of nutrients?', 'Un aliment peut-il contenir plusieurs types de nutriments ?')],
    retentionOptions: [{ en: ['For growth, repair and many regulatory processes', 'Only to change body appearance', 'Food has no role in body materials'], fr: ['Pour croissance, réparation et de nombreuses régulations', 'Seulement pour changer l’apparence', 'Les aliments n’apportent aucun matériau au corps'] }, { en: ['Yes; foods commonly contain several nutrients', 'No; every food contains exactly one nutrient', 'Only foods from another country can'], fr: ['Oui ; les aliments en contiennent souvent plusieurs', 'Non ; chaque aliment contient exactement un nutriment', 'Seulement les aliments venant d’un autre pays'] }],
    criteria: [tx('Inspect independent food/nutrient/function explanations and the actual fictional-case comparison, covering the source’s need-for-feeding reasoning.', 'Examiner les explications autonomes et la vraie comparaison fictive, couvrant le raisonnement sur les besoins alimentaires.'), tx('Require respectful evidence labels, multi-nutrient understanding and explicit appearance limits; no body diagnosis, fasting task or invented observation.', 'Exiger respect, nature des preuves, pluralité des nutriments et limites de l’apparence ; aucun diagnostic, jeûne expérimental ni observation inventée.')],
  }),
  unit(54, {
    title: tx('Following food through the digestive system', 'Suivre les aliments dans l’appareil digestif'),
    subskills: ['identify-alimentary-canal', 'explain-stage-specific-digestion', 'draw-and-research-food-pathway'], misconception: 'places-large-intestine-before-small-intestine',
    explanation: tx('The food pathway is mouth → oesophagus → stomach → small intestine → large intestine → rectum → anus. Chewing breaks food physically; saliva moistens it and begins starch digestion. Muscular movements carry it along the oesophagus. The stomach mixes it with acid and enzymes, including those involved in protein breakdown. In the small intestine, digestive juices, including contributions from the pancreas and bile from the liver, support further breakdown; most nutrient absorption occurs here. Bile helps fat processing but is not an enzyme. The large intestine absorbs remaining water and helps form faeces. Digestion is breaking down food; absorption moves digested substances into the body; egestion removes undigested waste. These are different processes.', 'Le trajet est bouche → œsophage → estomac → intestin grêle → gros intestin → rectum → anus. Mâcher fragmente les aliments ; la salive les humidifie et commence la digestion de l’amidon. Des mouvements musculaires les font avancer. L’estomac mélange avec acide et enzymes, dont certaines interviennent sur les protéines. Dans l’intestin grêle, des sucs digestifs, ceux du pancréas et la bile du foie participent à la poursuite de la digestion ; l’essentiel de l’absorption s’y produit. La bile facilite le traitement des lipides sans être une enzyme. Le gros intestin absorbe de l’eau et contribue à former les selles. Digérer transforme les aliments ; absorber fait passer des substances dans le corps ; évacuer élimine les résidus non digérés.'),
    example: tx('Trace boiled yam and egg on a labelled drawing. At the mouth mark chewing and saliva acting on starch. At the stomach mark mixing and protein digestion beginning; at the small intestine show further carbohydrate/protein/fat digestion and absorption. At the large intestine mark water absorption and waste formation. Research the explanation in a checked school text or NIH/NIDDK teaching source; do not claim to have watched food inside a real person.', 'Sur un dessin légendé, suis igname bouillie et œuf. Dans la bouche, indique mastication et action salivaire sur l’amidon ; dans l’estomac, mélange et début de digestion des protéines ; dans l’intestin grêle, poursuite de la digestion et absorption ; dans le gros intestin, absorption d’eau et formation des selles. Vérifie avec un manuel ou une ressource NIH/NIDDK, sans prétendre observer l’intérieur d’une personne.'),
    question: tx('Which sequence correctly follows food after the stomach?', 'Quel trajet suit correctement les aliments après l’estomac ?'),
    options: { en: ['Small intestine, then large intestine', 'Large intestine, then small intestine', 'Liver, then the lungs as the normal food tube'], fr: ['Intestin grêle, puis gros intestin', 'Gros intestin, puis intestin grêle', 'Foie puis poumons comme conduit alimentaire normal'] },
    correction: tx('Follow the tube rather than the size of organ names. Food leaves the stomach for the small intestine and then the large intestine. Liver and pancreas contribute secretions; food does not normally pass through them as part of the canal. Redraw the arrows and retry.', 'Suis le conduit plutôt que la taille évoquée par les noms. Après l’estomac viennent intestin grêle puis gros intestin. Foie et pancréas apportent des sécrétions, sans être traversés normalement par les aliments. Corrige les flèches et réessaie.'),
    tasks: [tx('Independently research what happens to a starchy food, egg/meat, fruit and palm oil at the mouth, stomach, small intestine and large intestine. Cite checked sources. Draw and label the full alimentary canal and explain physical breakdown, chemical digestion, absorption and waste passage. Your teacher must inspect the actual diagram and researched notes.', 'Recherche seul le devenir d’un féculent, d’œuf/viande, de fruit et d’huile de palme dans bouche, estomac, intestin grêle et gros intestin. Cite les sources vérifiées. Dessine le conduit complet et explique fragmentation, digestion chimique, absorption et résidus. L’enseignant examine schéma et notes.'), tx('Use a different familiar meal to independently label a digestive-system drawing and explain stage-specific changes. Distinguish alimentary canal from organs supplying digestive juices and correct any confusion between digestion, absorption and egestion. Show original research notes for teacher review.', 'Avec un autre repas familier, légende seul l’appareil et explique les transformations selon les étapes. Distingue conduit et organes apportant les sucs et corrige les confusions digestion/absorption/évacuation. Présente les notes originales à l’enseignant.')],
    transfer: [tx('Correct a fictional diagram putting the large intestine before the small intestine and sending food through the liver. Explain every correction using checked sources and independently trace a new local food combination.', 'Corrige un schéma fictif plaçant le gros intestin avant l’intestin grêle et faisant traverser le foie aux aliments. Justifie les corrections avec des sources et suis seul un nouvel ensemble d’aliments locaux.'), tx('A learner says chewing finishes all digestion and the stomach absorbs every nutrient. Produce your own annotated pathway explaining why both claims are wrong, with evidence for different organ roles.', 'Un élève dit que mâcher termine toute digestion et que l’estomac absorbe tous les nutriments. Produis ton trajet annoté réfutant les deux affirmations avec les rôles documentés des organes.')],
    retention: [tx('Where does most nutrient absorption occur?', 'Où se produit l’essentiel de l’absorption des nutriments ?'), tx('Which statement distinguishes digestion from absorption?', 'Quelle affirmation distingue digestion et absorption ?')],
    retentionOptions: [{ en: ['Small intestine', 'Teeth alone', 'Lungs'], fr: ['Dans l’intestin grêle', 'Seulement dans les dents', 'Dans les poumons'] }, { en: ['Digestion breaks food down; absorption moves products into the body', 'They are exactly the same event', 'Absorption means chewing harder'], fr: ['La digestion transforme ; l’absorption fait passer les produits dans le corps', 'Ce sont exactement le même événement', 'Absorber signifie mâcher plus fort'] }],
    criteria: [tx('Inspect the independent labelled canal, correct order, researched local-food changes and stage-specific explanations.', 'Examiner conduit légendé, ordre exact, recherches sur les aliments locaux et explications par étape.'), tx('Check source citations and distinctions among digestion/absorption/egestion, canal and accessory organs; no invented internal observations.', 'Vérifier références et distinctions entre processus, conduit et organes annexes ; aucune observation interne inventée.')],
  }),
  unit(55, {
    title: tx('Digestion products, absorption and food-test evidence', 'Produits de digestion, absorption et tests alimentaires'),
    subskills: ['link-nutrients-to-digestion-products', 'explain-intestinal-absorption', 'perform-and-interpret-food-tests'], misconception: 'treats-food-test-results-as-proof-of-absorption',
    explanation: tx('Starch is broken down to simple sugars such as glucose; proteins to amino acids; fats/oils to smaller lipid products commonly introduced as fatty acids and glycerol. These products cross the small-intestinal lining: sugars and amino acids enter blood, while many fat products are transported via lymph before reaching blood. Villi increase the absorbing surface. A food test identifies a response associated with a sample’s contents; it does not show food being absorbed in a person. Typical school principles include a blue-black iodine response for starch, a changed Benedict’s response for reducing sugars in an approved heated test, a purple Biuret response for protein and an approved lipid test such as persistent translucent paper marking. A reducing-sugar test is not uniquely specific to glucose. Actual practical work requires a qualified teacher’s approved protocol, controls and direct observation; never taste test materials or improvise chemical/heating steps.', 'L’amidon devient des sucres simples comme le glucose ; les protéines, des acides aminés ; les lipides/huiles, des produits plus petits présentés ici comme acides gras et glycérol. Ils traversent la paroi de l’intestin grêle : sucres et acides aminés passent dans le sang, beaucoup de produits lipidiques transitent par la lymphe. Les villosités augmentent la surface. Un test renseigne sur le contenu d’un échantillon, pas sur l’absorption chez une personne. Principes scolaires : coloration bleu-noir à l’iode pour l’amidon, changement avec Benedict pour les sucres réducteurs dans un test chauffé approuvé, violet avec Biuret pour les protéines, et test lipidique autorisé comme une tache translucide persistante. Le test des sucres réducteurs n’identifie pas exclusivement le glucose. Il faut protocole approuvé, témoins, supervision qualifiée et observation directe ; aucun goûtage ni improvisation de réactifs/chauffage.'),
    example: tx('Build a chart: starch → simple sugars; protein → amino acids; oils → smaller lipid products. Add the intestinal wall and blood/lymph arrows. In a fictional test record, an iodine response supports starch in the sample; it says nothing about a learner’s absorption. For real laboratory work, use labelled known controls, record actual responses and follow only the teacher’s checked protocol. Blank results remain blank until observed.', 'Construis un tableau amidon → sucres simples ; protéines → acides aminés ; huiles → produits lipidiques plus petits. Ajoute paroi, sang et lymphe. Dans un résultat fictif, l’iode indique de l’amidon dans l’échantillon, pas l’absorption d’un élève. Au laboratoire réel, utilise les témoins identifiés, note les réponses réelles et suis uniquement le protocole vérifié de l’enseignant. Une case reste vide avant l’observation.'),
    question: tx('What does a positive school starch test establish?', 'Que permet d’établir un test scolaire positif de l’amidon ?'),
    options: { en: ['A response supporting starch in the tested sample, not proof of bodily absorption', 'That every nutrient has already entered a person’s blood', 'That the sample is safe to eat after testing'], fr: ['Une réponse en faveur d’amidon dans l’échantillon, sans preuve d’absorption corporelle', 'Que tous les nutriments sont déjà passés dans le sang', 'Que l’échantillon est consommable après le test'] },
    correction: tx('Ask what was actually measured. A sample’s indicator response is evidence about its contents. Absorption is a different biological process across the intestinal wall. Link the result only to the tested sample and do not infer eating safety or a person’s health. Retry.', 'Demande ce qui a réellement été mesuré. La réponse d’un échantillon renseigne sur son contenu. L’absorption est un autre processus à travers la paroi intestinale. Limite la conclusion à l’échantillon, sans potabilité/alimentation ni diagnostic, puis réessaie.'),
    tasks: [tx('Independently explain an approved animation of absorption and draw nutrient-to-product flow charts with blood/lymph routes at an appropriate level. Under direct qualified teacher supervision, carry out the permitted learner steps in approved starch, known-glucose/reducing-sugar, protein and fat/oil tests with controls. Record genuine observations and limits. Your teacher must inspect notes and directly verify practical performance; missing equipment or an unperformed test stays pending.', 'Explique seul une animation approuvée de l’absorption et dessine les produits avec trajets sang/lymphe au niveau adapté. Sous observation qualifiée directe, réalise les étapes d’élève autorisées des tests approuvés d’amidon, glucose connu/sucres réducteurs, protéines et lipides, avec témoins. Note observations et limites. L’enseignant vérifie directement la pratique ; tout test absent ou non réalisé reste en attente.'), tx('Using another teacher-approved sample set and checked laboratory protocol, independently explain expected nutrient breakdown and absorption, perform your authorised practical roles and compare actual responses with controls. Discuss why reducing-sugar evidence alone does not uniquely identify glucose or demonstrate absorption. Request review of the real laboratory record.', 'Avec d’autres échantillons et un protocole vérifié, explique seul digestion/absorption, réalise ton rôle pratique autorisé et compare les réponses aux témoins. Explique pourquoi un test réducteur seul n’identifie pas uniquement le glucose ni l’absorption. Fais examiner le vrai cahier de laboratoire.')],
    transfer: [tx('Evaluate a fictional report that turns positive food-test colours into a claim about someone’s digestion. Independently correct the inference and design a new evidence table. Demonstrate any new practical test only when the qualified teacher approves and observes it; do not invent results.', 'Évalue un rapport fictif déduisant la digestion d’une personne de couleurs de tests alimentaires. Corrige seul l’inférence et conçois un tableau de preuves. Toute nouvelle pratique exige autorisation et observation qualifiées ; aucun résultat inventé.'), tx('For a new approved food mixture, predict possible test responses with reasons, distinguish predictions from observed results and explain which digestion products would later be absorbed. Complete actual permitted tests under direct supervision if available; otherwise keep practical evidence pending.', 'Pour un nouveau mélange approuvé, prévois les réponses possibles avec raisons, distingue prévisions et observations et explique les produits ensuite absorbés. Réalise les tests permis sous supervision si disponibles ; sinon garde la pratique en attente.')],
    retention: [tx('What are the main end products used to describe protein digestion here?', 'Quels produits décrit-on ici à l’issue de la digestion des protéines ?'), tx('Why are villi relevant to absorption?', 'Pourquoi les villosités interviennent-elles dans l’absorption ?')],
    retentionOptions: [{ en: ['Amino acids', 'Unchanged starch grains only', 'Whole bones'], fr: ['Les acides aminés', 'Seulement des grains d’amidon inchangés', 'Des os entiers'] }, { en: ['They increase the intestinal absorbing surface', 'They replace the mouth’s teeth', 'They prove every food test is glucose-specific'], fr: ['Elles augmentent la surface d’absorption intestinale', 'Elles remplacent les dents', 'Elles rendent tout test spécifique au glucose'] }],
    criteria: [tx('Inspect independent product/absorption diagrams and actual controlled laboratory records for starch, glucose/reducing sugars, protein and lipids.', 'Examiner schémas autonomes et vrais relevés avec témoins pour amidon, glucose/sucres réducteurs, protéines et lipides.'), tx('Require directly observed permitted learner practical work for practical credit; a quiz, prediction, animation or teacher-only demonstration cannot establish the learner’s performance.', 'Exiger une pratique d’élève autorisée directement observée ; quiz, prévision, animation ou démonstration uniquement magistrale ne prouvent pas sa réalisation.'), tx('Check test specificity, unperformed tasks and distinction between sample composition, digestion and absorption.', 'Vérifier spécificité, tâches non réalisées et distinction composition, digestion et absorption.')],
  }),
];

B7_SCIENCE_SYSTEMS.push(
  unit(56, {
    title: tx('Inner planets, orbits and the Milky Way', 'Planètes internes, orbites et Voie lactée'),
    subskills: ['identify-inner-planets-and-properties', 'distinguish-galaxy-system-and-orbit', 'construct-and-explain-solar-system-model'], misconception: 'confuses-a-galaxy-with-the-solar-system',
    explanation: tx('The four inner planets are Mercury, Venus, Earth and Mars, in increasing distance from the Sun. They are rocky planets inside the main asteroid belt. Mercury is smallest and nearest the Sun; Venus has a thick atmosphere and a very hot surface; Earth has abundant surface liquid water; Mars has a thin atmosphere and a rusty-looking surface. An orbit is the path around the Sun; planetary orbits are ellipses, often close to circles, with the Sun at one focus. Rotation is spinning on an axis. The solar system includes the Sun and orbiting objects; the Milky Way is the much larger galaxy containing our solar system and many other stars. A classroom model cannot usually show correct planet sizes and distances at the same scale.', 'Les quatre planètes internes sont Mercure, Vénus, Terre et Mars, par distance croissante au Soleil. Elles sont rocheuses et situées à l’intérieur de la ceinture principale d’astéroïdes. Mercure est la plus petite et la plus proche ; Vénus possède une atmosphère épaisse et une surface très chaude ; la Terre beaucoup d’eau liquide en surface ; Mars une atmosphère ténue et un aspect rouillé. Une orbite est le trajet autour du Soleil : une ellipse souvent proche d’un cercle, le Soleil occupant un foyer. La rotation est le mouvement sur un axe. Le système solaire comprend le Soleil et ses objets ; la Voie lactée est la galaxie beaucoup plus vaste qui le contient avec de nombreuses étoiles. Un modèle de classe ne respecte généralement pas à la fois tailles et distances à la même échelle.'),
    example: tx('Place labelled paper markers in order: Sun, Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Highlight the inner four and sketch restrained elliptical paths rather than very stretched loops. Add a separate box “Milky Way contains our solar system”; it is not another planet. State “order model, not to scale” and explain that a star and a planet are different objects.', 'Place les étiquettes Soleil, Mercure, Vénus, Terre, Mars, Jupiter, Saturne, Uranus, Neptune. Surligne les quatre internes et dessine des ellipses peu étirées. Ajoute un encadré « La Voie lactée contient notre système solaire » ; ce n’est pas une planète. Indique « modèle d’ordre, non à l’échelle » et distingue étoile et planète.'),
    question: tx('Which statement correctly relates the solar system to the Milky Way?', 'Quelle affirmation relie correctement système solaire et Voie lactée ?'),
    options: { en: ['Our solar system is part of the Milky Way galaxy', 'The Milky Way is the fifth inner planet', 'The solar system contains every galaxy'], fr: ['Notre système solaire fait partie de la Voie lactée', 'La Voie lactée est la cinquième planète interne', 'Le système solaire contient toutes les galaxies'] },
    correction: tx('Separate scales. Mercury through Mars are planets; the Sun is a star; the solar system is within a galaxy called the Milky Way. Redraw the containing boxes rather than placing a galaxy in the planet sequence, then retry.', 'Distingue les échelles : Mercure à Mars sont des planètes ; le Soleil une étoile ; le système solaire appartient à la Voie lactée. Refais les encadrés d’inclusion au lieu d’ajouter une galaxie à la suite des planètes, puis réessaie.'),
    tasks: [tx('Using checked pictures/video, independently name and describe all four inner planets, explain a galaxy and the Milky Way, and distinguish rotation from elliptical orbital motion. Design and construct a safe labelled solar-system model, identify the inner four and explain its size/distance limitations. Your teacher must inspect the actual model and hear your own explanation.', 'Avec des images/vidéos vérifiées, nomme et décris seul les quatre planètes internes, explique galaxie et Voie lactée et distingue rotation et orbite elliptique. Conçois et construis un modèle sûr légendé du système solaire, repère les quatre internes et explique les limites d’échelle. L’enseignant voit le vrai modèle et écoute ton explication.'), tx('Construct a different independently designed paper/card solar-system model from an approved reference. Annotate inner-planet properties, the Sun’s place on an orbit diagram and the relation to the Milky Way. Explain why the model cannot establish actual planet diameters or separation without a stated scale.', 'Construis seul un autre modèle en papier/carton à partir d’une référence approuvée. Annote propriétés des planètes internes, place du Soleil sur une orbite et relation à la Voie lactée. Explique pourquoi tailles et distances réelles nécessitent une échelle explicite.')],
    transfer: [tx('Correct a fictional model that labels the Sun as a planet, puts Mars before Earth and calls the Milky Way an orbit. Independently build an improved labelled model, justify each change and state what remains not to scale.', 'Corrige un modèle fictif appelant le Soleil planète, plaçant Mars avant la Terre et nommant la Voie lactée « orbite ». Construis seul une version corrigée, justifie chaque changement et précise les limites d’échelle.'), tx('Design a new classroom explanation using containing diagrams for planet, solar system and galaxy plus an inner-planet orbit model. Compare this to a teacher-supplied picture, keeping model conventions distinct from measured sizes.', 'Conçois une explication avec schémas d’inclusion planète/système/galaxie et modèle d’orbites internes. Compare à une image fournie en distinguant conventions et dimensions mesurées.')],
    retention: [tx('Which is the correct order of the four inner planets from the Sun?', 'Quel est l’ordre des quatre planètes internes depuis le Soleil ?'), tx('What does rotation mean for a planet?', 'Que signifie la rotation d’une planète ?')],
    retentionOptions: [{ en: ['Mercury, Venus, Earth, Mars', 'Venus, Mercury, Mars, Earth', 'Earth, Jupiter, Saturn, Neptune'], fr: ['Mercure, Vénus, Terre, Mars', 'Vénus, Mercure, Mars, Terre', 'Terre, Jupiter, Saturne, Neptune'] }, { en: ['Spinning on its axis', 'Being a galaxy', 'Only moving through a drawn label'], fr: ['Tourner sur son axe', 'Être une galaxie', 'Traverser seulement une étiquette dessinée'] }],
    criteria: [tx('Inspect the real independently designed model, correct inner-planet names/order/properties and elliptical-orbit explanation.', 'Examiner le vrai modèle conçu seul, les noms/ordre/propriétés et l’explication des orbites elliptiques.'), tx('Check galaxy/solar-system distinction, rotation/orbit distinction and explicit model-scale limitations; a quiz cannot establish construction.', 'Vérifier galaxie/système, rotation/orbite et limites d’échelle ; un quiz ne prouve pas la construction.')],
  }),
  unit(57, {
    title: tx('Comparing Mercury and Venus', 'Comparer Mercure et Vénus'),
    subskills: ['compare-mercury-venus-properties', 'distinguish-orbit-and-rotation', 'interpret-relative-orbital-periods'], misconception: 'assumes-closest-planet-is-hottest-or-confuses-spin-with-orbit',
    explanation: tx('Mercury is nearest the Sun, small, rocky and heavily cratered, with only a very thin exosphere. Venus is second, rocky, similar in size to Earth and surrounded by a dense atmosphere with a strong greenhouse effect. Venus is hotter at its surface despite being farther from the Sun. Both travel around the Sun on elliptical orbits. Mercury completes an orbit in about 88 Earth days and Venus in about 225: Mercury has the shorter year and higher average orbital speed. These numbers describe orbital periods, not spin periods. Venus rotates very slowly in the opposite direction to most planets, but this does not mean its orbit around the Sun runs backwards relative to Mercury’s. Use a labelled perspective when showing motions.', 'Mercure est la plus proche du Soleil, petite, rocheuse et cratérisée, avec une exosphère très ténue. Vénus est la deuxième, rocheuse, proche de la Terre en taille et enveloppée d’une atmosphère dense produisant un fort effet de serre. Sa surface est plus chaude malgré sa distance supérieure. Toutes deux parcourent des orbites elliptiques. Mercure fait un tour en environ 88 jours terrestres, Vénus en 225 : l’année de Mercure est plus courte et sa vitesse orbitale moyenne plus élevée. Ces durées concernent l’orbite, pas la rotation. Vénus tourne lentement sur elle-même en sens opposé à la plupart des planètes, sans inverser son sens orbital par rapport à Mercure. Indique le point de vue de tes schémas.'),
    example: tx('Make separate columns for distance order, surface/atmosphere, orbital period and rotation direction. Put 88 and 225 only in the orbital-period column. On a top-view model, trace both orbits in the same overall direction while using a separate spin arrow to show Venus’s unusual rotation. Explain why distance alone does not determine surface temperature.', 'Sépare rang de distance, surface/atmosphère, période orbitale et sens de rotation. Place 88 et 225 uniquement dans la colonne orbitale. Sur une vue du dessus, fais tourner les deux marqueurs dans le même sens orbital général et montre séparément la rotation particulière de Vénus. Explique pourquoi la distance seule ne fixe pas la température.'),
    question: tx('Mercury orbits in about 88 Earth days and Venus in about 225. Which conclusion follows?', 'Mercure orbite en environ 88 jours terrestres et Vénus en 225. Quelle conclusion en découle ?'),
    options: { en: ['Mercury completes a solar orbit sooner than Venus', 'Venus must finish an orbit every 88 days', 'The figures prove both planets spin once every 24 hours'], fr: ['Mercure termine une orbite solaire plus vite que Vénus', 'Vénus termine forcément une orbite en 88 jours', 'Ces nombres prouvent une rotation de 24 heures pour les deux'] },
    correction: tx('Compare like quantities: 88 and 225 are times for one trip around the Sun. The smaller period is Mercury’s. Do not turn orbital time into a spin period. Identify the two different arrows on your model and retry.', 'Compare la même grandeur : 88 et 225 sont les durées d’un tour autour du Soleil. La plus courte appartient à Mercure. N’en déduis pas la durée de rotation. Distingue les deux flèches du modèle et réessaie.'),
    tasks: [tx('Independently prepare a checked-source comparison of Mercury and Venus: rocky surfaces, atmospheric differences, temperature explanation, relative positions and orbital periods. Draw their elliptical paths with a stated viewpoint, distinguish orbit from rotation and explain the shorter Mercury year. Your teacher reviews the table and your own motion explanation.', 'Prépare seul une comparaison documentée : surfaces rocheuses, atmosphères, température, positions relatives et périodes orbitales. Dessine les trajets elliptiques avec point de vue, distingue orbite/rotation et explique l’année plus courte de Mercure. L’enseignant examine tableau et explication.'), tx('Using another approved reference, independently explain two distinctive properties of each planet and demonstrate orbital versus rotational motion with labelled markers. Interpret the 88/225-day comparison and explain why Venus can be hotter and rotate differently without reversing its solar orbit.', 'Avec une autre référence approuvée, explique seul deux propriétés de chaque planète et démontre orbite/rotation avec des marqueurs. Interprète 88/225 jours et explique pourquoi Vénus peut être plus chaude et tourner différemment sans inverser son orbite solaire.')],
    transfer: [tx('Correct a fictional astronomy card saying “Mercury is hottest because it is nearest; Venus’s reverse spin means a reverse orbit”. Use checked evidence and a new annotated motion diagram to explain both errors.', 'Corrige une carte fictive disant « Mercure est la plus chaude car la plus proche ; la rotation inverse de Vénus inverse son orbite ». Utilise des preuves vérifiées et un nouveau schéma de mouvements.'), tx('For a teacher-provided time interval of 225 Earth days, explain qualitatively how Mercury can complete more than one orbit while Venus completes about one. State that a simplified model does not show exact simultaneous positions or a 24-hour spin.', 'Sur un intervalle fourni de 225 jours terrestres, explique qualitativement que Mercure peut faire plus d’une orbite pendant que Vénus en fait environ une. Précise que le modèle ne donne ni positions simultanées exactes ni rotation de 24 heures.')],
    retention: [tx('Which planet has the hotter surface in this comparison?', 'Quelle planète a la surface la plus chaude dans cette comparaison ?'), tx('Does Venus’s unusual spin imply an opposite solar-orbit direction?', 'La rotation particulière de Vénus implique-t-elle un sens orbital solaire opposé ?')],
    retentionOptions: [{ en: ['Venus, with its dense greenhouse atmosphere', 'Mercury simply because it is nearer', 'Both always have identical temperatures'], fr: ['Vénus, avec son atmosphère dense à effet de serre', 'Mercure uniquement parce qu’elle est plus proche', 'Les deux ont toujours la même température'] }, { en: ['No; spin and orbital direction are different motions', 'Yes; they are exactly the same motion', 'There is no Sun in either orbit'], fr: ['Non ; rotation et déplacement orbital sont distincts', 'Oui ; c’est exactement le même mouvement', 'Le Soleil est absent des deux orbites'] }],
    criteria: [tx('Check independently explained properties, correct approximate orbital periods and a clearly labelled motion comparison.', 'Vérifier propriétés expliquées seul, périodes approximatives correctes et comparaison de mouvements légendée.'), tx('Reject distance-only temperature reasoning and rotation/orbit conflation; require checked sources rather than copied unsupported claims.', 'Refuser température déduite de la seule distance et confusion rotation/orbite ; exiger des références vérifiées.')],
  }),
  unit(58, {
    title: tx('Ecosystem components and interactions', 'Composantes et interactions des écosystèmes'),
    subskills: ['identify-biotic-and-abiotic-components', 'compare-habitats-and-organisms', 'explain-component-interactions'], misconception: 'treats-an-ecosystem-as-closed-or-arboreal-as-exclusive',
    explanation: tx('An ecosystem includes organisms and non-living surroundings interacting in a place. Biotic components include plants, animals and microorganisms; abiotic components include water, light, temperature, air and mineral surroundings. A pond is aquatic; a field or forest is terrestrial; arboreal describes tree-associated habitats within a wider ecosystem. These labels need not be mutually exclusive. Plants use light and supply food or shelter; animals feed, disperse seeds or alter surroundings; decomposers return materials to nutrient cycles. The source’s “self-sustaining” description concerns interacting processes, not a sealed system making its own energy: ecosystems exchange energy and often matter with their surroundings. Changes in water, shade or organisms can affect other components. Distinguish an observed interaction from a plausible hypothesis.', 'Un écosystème réunit êtres vivants et milieu non vivant en interaction. Les composantes biotiques comprennent plantes, animaux et micro-organismes ; les abiotiques, eau, lumière, température, air et milieu minéral. Une mare est aquatique ; champ et forêt terrestres ; arboricole décrit des habitats liés aux arbres dans un ensemble plus large. Ces catégories peuvent se recouper. Les plantes utilisent la lumière et offrent nourriture ou abri ; les animaux se nourrissent, dispersent des graines ou modifient le milieu ; les décomposeurs recyclent la matière. « Autosuffisant » dans la source évoque des processus liés, pas un système fermé créant son énergie : les écosystèmes échangent énergie et souvent matière. Une modification peut affecter plusieurs composantes. Distingue interaction observée et hypothèse.'),
    example: tx('From an approved school-tree picture, list leaves, insects and birds as biotic, and light, air and water as abiotic. Label tree-associated activity arboreal within a terrestrial setting. Draw plant → insect → bird feeding links and light → plant as an energy-input link, explaining arrow meanings. Compare with an approved pond picture and do not invent unseen organisms or enter water/climb trees.', 'Dans une image approuvée d’arbre scolaire, classe feuilles, insectes et oiseaux comme biotiques ; lumière, air et eau comme abiotiques. L’activité arboricole appartient ici à un milieu terrestre. Trace plante → insecte → oiseau et lumière → plante en expliquant les flèches. Compare une image de mare sans inventer d’organismes invisibles ni entrer dans l’eau ou grimper.'),
    question: tx('Which pair correctly contrasts a biotic and an abiotic component?', 'Quelle paire oppose correctement une composante biotique et une abiotique ?'),
    options: { en: ['Living grass and sunlight', 'Sunlight and water as two living organisms', 'Two birds as one living and one non-living factor'], fr: ['Herbe vivante et lumière solaire', 'Lumière et eau comme deux organismes vivants', 'Deux oiseaux comme facteur vivant et non vivant'] },
    correction: tx('Ask whether the component is an organism or part of its non-living environment. Grass is living; sunlight is an abiotic energy input. Both matter in an ecosystem, but they play different roles. Relabel the components and retry.', 'Demande si la composante est un organisme ou un élément non vivant. L’herbe est vivante ; la lumière est un apport énergétique abiotique. Les deux comptent sans jouer le même rôle. Corrige les étiquettes et réessaie.'),
    tasks: [tx('Independently compare approved terrestrial, aquatic and tree-associated ecosystem examples. Identify organisms and abiotic factors, distinguish the organisms across habitats and explain at least two component interactions in each example using labelled diagrams. Explain openness and overlapping habitat labels. Your teacher must inspect the actual comparison and reasoning; clearly label observations, source information and hypotheses.', 'Compare seul des exemples approuvés terrestres, aquatiques et arboricoles. Identifie organismes et facteurs abiotiques, distingue les êtres vivants et explique au moins deux interactions par exemple avec des schémas. Explique échanges et recoupements des catégories. L’enseignant examine le travail ; distingue observations, informations de source et hypothèses.'), tx('Use a different approved set of habitat pictures or safe supervised observations to create your own component table and interaction network. Explain the effect of a change in light/water or one organism, compare habitats and cite the evidence without claiming the system generates energy itself.', 'Avec un autre ensemble d’images ou des observations sûres supervisées, crée ton tableau et réseau d’interactions. Explique une variation de lumière/eau ou d’organisme, compare les habitats et cite les preuves sans création autonome d’énergie.')],
    transfer: [tx('For a fictional school garden receiving less water, independently predict effects on plants, animals and non-living factors. Draw causal links, distinguish prediction from evidence and explain what further observation would test your reasoning.', 'Pour un jardin fictif recevant moins d’eau, prévois seul les effets sur plantes, animaux et facteurs non vivants. Trace les causes, distingue prévision et preuve et propose une vérification.'), tx('Correct a diagram that labels all tree life non-terrestrial and omits external light. Build a new interaction model comparing tree and pond examples and explain the limits of a simplified ecosystem model.', 'Corrige un schéma excluant toute vie arboricole du terrestre et oubliant la lumière extérieure. Crée un nouveau modèle comparant arbre et mare et explique ses limites.')],
    retention: [tx('Can an arboreal habitat also be part of a terrestrial ecosystem?', 'Un habitat arboricole peut-il appartenir à un écosystème terrestre ?'), tx('What is needed to justify a claimed observed interaction?', 'Que faut-il pour justifier une interaction présentée comme observée ?')],
    retentionOptions: [{ en: ['Yes; the labels can overlap', 'No; every category must be completely separate', 'Only if trees are non-living'], fr: ['Oui ; les catégories peuvent se recouper', 'Non ; elles doivent toujours être entièrement séparées', 'Seulement si les arbres sont non vivants'] }, { en: ['Actual observation or a clearly identified checked source', 'A prediction relabelled as fact', 'Only a confident guess'], fr: ['Une vraie observation ou une source vérifiée clairement citée', 'Une prévision renommée comme fait', 'Seulement une supposition assurée'] }],
    criteria: [tx('Inspect independent habitat/component comparisons and interaction diagrams, covering all source categories without false exclusivity.', 'Examiner comparaisons et schémas autonomes couvrant toutes les catégories sans exclusion artificielle.'), tx('Check biotic/abiotic roles, organism differences, energy/matter exchange and evidence-versus-hypothesis reasoning.', 'Vérifier rôles, différences entre organismes, échanges et distinction preuve/hypothèse.')],
  }),
);

B7_SCIENCE_SYSTEMS.push(
  unit(60, {
    title: tx('How farming systems differ', 'Distinguer les systèmes agricoles'),
    subskills: ['define-five-farming-systems', 'compare-practices-over-time-and-space', 'explain-local-and-other-context-examples'], misconception: 'confuses-mixed-cropping-with-mixed-farming',
    explanation: tx('Land rotation changes the cultivated plot and allows other previously used land to rest/fallow. Crop rotation changes crops in a planned sequence on the same plot over seasons. Mixed cropping grows two or more crops in the same area during the same period. In the school contrast used here, mixed farming combines crop and livestock enterprises on a farm. Organic farming is an ecosystem-oriented management approach involving soil building, nutrient cycling, diversity and appropriate biological/cultural methods, rather than simply adding compost once. These descriptions concern different dimensions, so a farm can combine rotation, mixed crops and organic practices. Land rotation is not an instruction to clear new forest. Examine checked examples in Ghana and elsewhere, stating what practice evidence supports each description rather than inferring it from a crop’s name.', 'La rotation des terres déplace la culture entre parcelles en laissant d’autres terres déjà utilisées au repos/en jachère. La rotation culturale change les cultures selon une suite planifiée sur la même parcelle au fil des saisons. Les cultures associées réunissent au moins deux cultures dans le même espace pendant la même période. Dans le contraste scolaire utilisé ici, la polyculture-élevage associe cultures et animaux sur une exploitation. L’agriculture biologique est une gestion écologique fondée sur sol, cycles, diversité et méthodes biologiques/culturales adaptées, pas un simple apport ponctuel de compost. Ces dimensions se recoupent. La rotation des terres n’ordonne pas de défricher une forêt. Examine des exemples vérifiés au Ghana et ailleurs en justifiant les pratiques, sans déduire un système du seul nom d’une plante.'),
    example: tx('Use five fictional cards: shift cultivation between existing plots with a fallow interval; alternate maize and cowpea on one plot across seasons; grow maize and cowpea together; keep crops and chickens on one farm; manage soil through an intentional checked organic-practice plan. Label the first four by plot/time/crop/enterprise evidence and the fifth by management evidence. A card can fit more than one description if the stated facts support it.', 'Utilise cinq cartes fictives : alterner des parcelles existantes avec jachère ; succéder maïs et niébé sur une parcelle ; les cultiver ensemble ; associer cultures et poules sur une ferme ; gérer le sol selon un plan biologique documenté. Justifie chaque classement par parcelle, temps, cultures, activités ou gestion. Une carte peut relever de plusieurs descriptions si les faits le montrent.'),
    question: tx('A farm grows crops and keeps livestock. Which school farming-system description directly fits?', 'Une exploitation cultive des plantes et élève des animaux. Quelle description scolaire convient directement ?'),
    options: { en: ['Mixed farming', 'Mixed cropping solely because animals are present', 'Crop rotation without evidence across seasons'], fr: ['La polyculture-élevage', 'Les cultures associées seulement parce qu’il y a des animaux', 'La rotation culturale sans information temporelle'] },
    correction: tx('Ask what is being combined. Two crops grown together support mixed cropping; crop and animal enterprises support mixed farming in this lesson. Rotation requires time or plot-change evidence. Identify the relevant evidence, then retry.', 'Demande ce qui est associé. Deux cultures simultanées appuient les cultures associées ; cultures et élevage appuient ici la polyculture-élevage. Une rotation exige des informations de temps ou parcelle. Repère les preuves et réessaie.'),
    tasks: [tx('Independently define land rotation, crop rotation, mixed cropping, mixed farming and organic farming. Use checked Ghanaian and other-context examples to compare cultivated plots, seasons, crops/animals and management. Write an actual comparison table and explain overlapping systems without inventing observations or certification. Teacher review is required.', 'Définis seul rotation des terres, rotation culturale, cultures associées, polyculture-élevage et agriculture biologique. Avec des exemples vérifiés du Ghana et d’ailleurs, compare parcelles, saisons, cultures/animaux et gestion. Produis un vrai tableau et explique les recoupements sans inventer observation ou certification. Examen requis.'), tx('Analyse a different teacher-approved set of farm descriptions. Independently explain all five systems, identify distinguishing practice evidence and compare their characteristics in Ghana. Explain why two simultaneous crops differ from crop/livestock integration and why rotation and organic practices may coexist.', 'Analyse un autre ensemble de descriptions approuvées. Explique seul les cinq systèmes, les preuves distinctives et leurs caractéristiques au Ghana. Distingue deux cultures simultanées et association cultures/élevage et explique la coexistence possible de rotation et pratiques biologiques.')],
    transfer: [tx('A fictional farm uses maize/cowpea rotation, grows some crops together and keeps poultry. Produce an independent multi-label description, justify each label and identify what additional evidence is needed before calling its management organic.', 'Une ferme fictive alterne maïs/niébé, associe certaines cultures et élève des volailles. Produis une description à plusieurs catégories, justifie chacune et précise les preuves nécessaires avant de parler de gestion biologique.'), tx('Correct a poster that calls every farm with two crops “mixed farming” and every compost use “certified organic”. Explain the school distinctions with new checked examples and avoid unsupported certification claims.', 'Corrige une affiche appelant toute ferme à deux cultures « polyculture-élevage » et tout compost « biologique certifié ». Explique les distinctions avec de nouveaux exemples vérifiés sans certification non prouvée.')],
    retention: [tx('What distinguishes crop rotation from mixed cropping?', 'Qu’est-ce qui distingue rotation culturale et cultures associées ?'), tx('Can one farm combine more than one of these systems?', 'Une exploitation peut-elle combiner plusieurs de ces systèmes ?')],
    retentionOptions: [{ en: ['Crops succeed over time versus growing together', 'Only the colour of the plants', 'Both necessarily require livestock'], fr: ['Succession dans le temps contre culture simultanée', 'Seulement la couleur des plantes', 'Les deux exigent nécessairement des animaux'] }, { en: ['Yes, if the practices support the labels', 'No; all labels are always exclusive', 'Only if observations are invented'], fr: ['Oui, si les pratiques justifient les catégories', 'Non ; toutes les catégories sont exclusives', 'Seulement en inventant des observations'] }],
    criteria: [tx('Inspect independent definitions and characteristics of all five source-listed systems with checked Ghana/other-context examples.', 'Examiner définitions et caractéristiques autonomes des cinq systèmes avec des exemples vérifiés du Ghana et d’ailleurs.'), tx('Check plot/time/enterprise/management distinctions, justified overlap and absence of invented certification or field observations.', 'Vérifier parcelle/temps/activités/gestion, recoupements justifiés et absence de certification ou terrain inventés.')],
  }),
  unit(61, {
    title: tx('Classifying farming descriptions and community evidence', 'Classer les descriptions agricoles et les preuves locales'),
    subskills: ['classify-by-practice-evidence', 'group-community-farming-records', 'identify-overlap-and-uncertainty'], misconception: 'assigns-a-system-without-time-plot-or-enterprise-evidence',
    explanation: tx('Classification requires evidence. Look for a change of cultivated plot plus fallow for land rotation, a planned crop sequence on the same plot for crop rotation, simultaneous crops for mixed cropping, crop/livestock enterprises for the school mixed-farming category, and a documented ecosystem-oriented management approach for organic farming. One maize plant or a bag of compost does not reveal the whole system. Collect safe, permitted community descriptions or records with dates and sources, then match the evidence to the categories. More than one label can apply. Missing evidence should be recorded as unknown, not repaired by guessing. Do not claim a local farm is certified from a classroom classification.', 'Un classement exige des preuves : changement de parcelle avec jachère pour rotation des terres ; succession planifiée sur la même parcelle pour rotation culturale ; cultures simultanées pour cultures associées ; cultures et élevage pour polyculture-élevage ; gestion écologique documentée pour agriculture biologique. Une plante de maïs ou un sac de compost ne révèle pas tout. Recueille des descriptions/documents locaux permis, datés et sourcés, puis associe les preuves aux catégories. Plusieurs catégories peuvent s’appliquer. Une information absente reste inconnue au lieu d’être devinée. Un classement de classe ne prouve aucune certification.'),
    example: tx('Make a decision table with columns plot, season/history, simultaneous crops, livestock, management evidence and category. A fictional record “maize this season, cowpea next season, same plot” supports crop rotation. “Maize observed today” does not establish a rotation. Add a genuine permitted community record only if obtained, label reports separately and keep missing fields unknown.', 'Fais un tableau parcelle, saison/historique, cultures simultanées, animaux, gestion et catégorie. « Maïs cette saison, niébé la suivante, même parcelle » appuie la rotation culturale. « Maïs vu aujourd’hui » ne la prouve pas. Ajoute un vrai document local seulement s’il a été obtenu, distingue témoignages et inconnues.'),
    question: tx('You see maize on one plot today but have no history. What can you conclude about crop rotation?', 'Tu vois du maïs aujourd’hui sans historique de la parcelle. Que conclus-tu sur la rotation culturale ?'),
    options: { en: ['Rotation is not established without crop-sequence evidence', 'A single sighting proves rotation', 'Every maize field is automatically organic'], fr: ['La rotation n’est pas établie sans preuve de succession', 'Une observation unique prouve la rotation', 'Tout champ de maïs est automatiquement biologique'] },
    correction: tx('A rotation is a pattern through time. A present crop shows only part of the record. Ask for a checked sequence or management record and leave the classification uncertain until supported. Retry without inventing a history.', 'La rotation est un schéma temporel. La culture actuelle n’en montre qu’une partie. Cherche un historique vérifié et conserve l’incertitude jusqu’à preuve suffisante. Réessaie sans inventer le passé.'),
    tasks: [tx('Independently classify teacher-provided descriptions under all five source categories, explaining the practice evidence and overlaps. Then group genuine permitted community farming records/descriptions under those categories, preserving dates, sources and uncertainties. Your teacher must inspect actual records and independent classifications; an unavailable community investigation stays pending rather than fictional.', 'Classe seul les descriptions fournies dans les cinq catégories, en justifiant pratiques et recoupements. Regroupe ensuite de vraies descriptions/documents locaux permis, avec dates, sources et incertitudes. L’enseignant examine les vrais documents et classements ; une enquête indisponible reste en attente, sans fiction présentée comme réelle.'), tx('Use another approved set of community records to create an independent evidence-to-category table for land/crop rotation, mixed cropping, mixed farming and organic farming. Explain unmatched or multi-label records, distinguish observed from reported practices and state where further evidence is required.', 'Avec d’autres documents locaux approuvés, crée seul un tableau preuves/catégories pour les cinq systèmes. Explique les cas sans catégorie ou à plusieurs catégories, distingue observations et témoignages et précise les preuves manquantes.')],
    transfer: [tx('Audit a new fictional community inventory that assigns each farm one confident label despite missing histories. Independently correct unsupported categories, allow justified overlap and prepare questions that would resolve uncertainty without claiming interviews occurred.', 'Audite un inventaire fictif attribuant une catégorie certaine malgré des historiques absents. Corrige seul les catégories, autorise les recoupements justifiés et prépare des questions sans prétendre avoir mené les entretiens.'), tx('Compare two new permitted community farm descriptions with similar crops but different seasonal or animal-management evidence. Explain why their classifications can differ and what remains unverified.', 'Compare deux nouvelles descriptions locales permises avec cultures semblables mais preuves saisonnières ou d’élevage différentes. Explique les classements possibles et les informations non vérifiées.')],
    retention: [tx('Which record directly supports mixed cropping?', 'Quel relevé appuie directement les cultures associées ?'), tx('How should unsupported classification evidence be handled?', 'Comment traiter une information insuffisante pour classer ?')],
    retentionOptions: [{ en: ['Two crops growing together in the same area and period', 'A crop succession on one plot only', 'A single animal without a crop record'], fr: ['Deux cultures ensemble au même endroit et à la même période', 'Seulement une succession sur une parcelle', 'Un animal seul sans information de culture'] }, { en: ['Record uncertainty and seek checked evidence', 'Invent the missing history', 'Choose the most impressive label'], fr: ['Noter l’incertitude et rechercher des preuves vérifiées', 'Inventer l’historique absent', 'Choisir la catégorie la plus impressionnante'] }],
    criteria: [tx('Inspect actual independent five-category classification and genuine scoped community evidence, retaining dates/sources.', 'Examiner le classement autonome des cinq catégories et les vraies preuves locales délimitées, datées et sourcées.'), tx('Check evidence-to-label reasoning, overlap, unknowns and observation/report distinctions; no fabricated fieldwork or certification.', 'Vérifier raisonnement, recoupements, inconnues et nature des preuves ; aucun terrain ni certification inventés.')],
  }),
  unit(62, {
    title: tx('Evaluating the usefulness of farming systems', 'Évaluer l’utilité des systèmes agricoles'),
    subskills: ['tabulate-contextual-reasons-for-systems', 'compare-benefits-and-limitations', 'participate-in-evidence-based-debate'], misconception: 'claims-one-system-is-always-best-without-context',
    explanation: tx('Usefulness depends on land, soil, water, labour, knowledge, inputs and goals. Land rotation may allow fallow recovery but requires sufficient suitable existing land and is constrained where land is limited. Crop rotation can help manage soil and crop-specific pest pressures, but needs suitable crop sequences. Mixed cropping can diversify output and use resources differently, but poorly chosen crops may compete. Mixed farming can link crops, feed and appropriately managed nutrients, but adds animal-care, labour and health-management demands. Organic management emphasises soil and ecological processes but requires planning, labour, verified practices and context-specific judgement; it is not a guarantee of harmlessness, profit or identical yields. Benefits are conditional, not promises. Debate reasons and trade-offs without instructing real land clearance or chemical use.', 'L’utilité dépend des terres, du sol, de l’eau, du travail, des connaissances, des intrants et des buts. La rotation des terres peut permettre une récupération en jachère mais exige des terres existantes suffisantes. La rotation culturale peut aider le sol et certains problèmes de ravageurs, selon les cultures choisies. Les cultures associées diversifient la production mais peuvent entrer en concurrence. La polyculture-élevage peut relier cultures, alimentation animale et nutriments bien gérés, avec davantage de soins et de travail. La gestion biologique privilégie sol et processus écologiques, sans garantir innocuité, profit ou rendement identique. Il faut planification et pratiques vérifiées. Compare les compromis sans ordonner défrichement ou utilisation de produits chimiques.'),
    example: tx('For a fictional school garden with little land and limited adult supervision, make a table for all five systems: reason for use, potential benefit, limitation and missing information. Land rotation may be impractical; a planned crop sequence may be feasible on paper. Do not select a winner without considering goals and evidence. Prepare one reasoned argument and one counterargument, then respond respectfully in a class debate.', 'Pour un jardin fictif avec peu de terrain et de supervision, fais un tableau des cinq systèmes : motif, avantage possible, limite et information absente. La rotation des terres peut être difficile ; une succession culturale peut être envisageable sur papier. Ne choisis pas de gagnant sans buts ni preuves. Prépare argument et contre-argument puis réponds respectueusement en débat.'),
    question: tx('Which evaluation is justified when choosing between farming-system options in a fictional case?', 'Quelle évaluation est justifiée pour comparer des systèmes dans un cas fictif ?'),
    options: { en: ['Compare benefits, constraints and evidence for the stated goals', 'Declare one system best everywhere without evidence', 'Assume every benefit guarantees a profit'], fr: ['Comparer avantages, contraintes et preuves selon les buts', 'Déclarer un système meilleur partout sans preuve', 'Supposer que tout avantage garantit un bénéfice financier'] },
    correction: tx('Use the stated conditions. A benefit can be outweighed by lack of land, labour, suitable crops or supervision. Explain both an argument and a limitation, identify missing evidence and retry. A conditional educational comparison is not a guarantee for a real farm.', 'Utilise les conditions données. Un avantage peut être limité par terres, travail, cultures ou supervision. Explique argument, limite et preuves manquantes puis réessaie. Une comparaison scolaire conditionnelle n’est pas une garantie pour une ferme réelle.'),
    tasks: [tx('Independently tabulate reasons, merits and demerits for all five source-listed farming systems using checked examples and stated contexts. Participate in an actual teacher-observed debate, explain your own evidence, address a counterargument and acknowledge uncertainty. Submit the real table and discussion notes; a written claim to have debated is insufficient.', 'Présente seul dans un tableau raisons, avantages et limites des cinq systèmes avec exemples vérifiés et contextes. Participe à un vrai débat observé, expose tes preuves, réponds à un contre-argument et reconnais l’incertitude. Présente tableau et notes ; prétendre avoir débattu par écrit ne suffit pas.'), tx('For a different fictional farming context, independently compare all five systems and prepare balanced arguments. Debate the trade-offs with partners under teacher observation, distinguish your contribution from group support and explain what further evidence would change your conclusion.', 'Pour un autre contexte fictif, compare seul les cinq systèmes et prépare des arguments équilibrés. Débats des compromis sous observation de l’enseignant, distingue ta contribution des aides et précise les preuves pouvant changer ta conclusion.')],
    transfer: [tx('A new fictional farm proposal promises unlimited yield from one system and ignores labour. Independently audit it with a benefit/constraint table, produce a conditional recommendation for the classroom case and defend it in an observed discussion without claiming real farm outcomes.', 'Une proposition fictive promet un rendement illimité et ignore le travail. Audite-la seul avec un tableau avantages/contraintes, formule une conclusion conditionnelle pour le cas scolaire et défends-la dans un échange observé sans inventer de résultats réels.'), tx('Compare two teacher-supplied contexts with different land and labour constraints. Explain why the same farming-system ranking may not fit both, then respond to a new counterargument using your independent evidence table.', 'Compare deux contextes fournis aux contraintes différentes de terre et travail. Explique pourquoi un même classement ne convient pas forcément aux deux puis réponds à un nouveau contre-argument avec ton tableau personnel.')],
    retention: [tx('Why might land rotation be difficult where suitable land is scarce?', 'Pourquoi la rotation des terres peut-elle être difficile quand les terres adaptées sont rares ?'), tx('What makes a debate contribution evidence-based?', 'Qu’est-ce qui rend une contribution au débat fondée sur des preuves ?')],
    retentionOptions: [{ en: ['It needs suitable land for alternating cultivation and fallow', 'Because it never involves land', 'Because every alternative is always harmful'], fr: ['Elle nécessite des terres pour alterner culture et jachère', 'Parce qu’elle n’utilise jamais de terres', 'Parce que toute autre solution est toujours nuisible'] }, { en: ['A justified claim, context, limits and response to counterevidence', 'Only repeating the loudest opinion', 'Inventing yields to win'], fr: ['Une affirmation justifiée, contexte, limites et réponse aux objections', 'Répéter seulement l’opinion la plus forte', 'Inventer des rendements pour gagner'] }],
    criteria: [tx('Inspect the independent five-system merits/demerits table, checked evidence and contextual reasons.', 'Examiner le tableau autonome des cinq systèmes, les preuves vérifiées et les raisons contextuelles.'), tx('Observe the actual debate/discussion, individual reasoning and response to a counterargument; no fictional participation or universal benefit guarantees.', 'Observer le vrai débat, le raisonnement individuel et la réponse à une objection ; aucune participation fictive ni garantie universelle.')],
  }),
);
